417	  <script>
418	    const dialog = document.querySelector('#add-dialog');
419	    const input = document.querySelector('#url');
420	    const form = document.querySelector('#bookmark-form');
421	    const saveButton = document.querySelector('#save-button');
422	    const emptyState = document.querySelector('#empty-state');
423	    const grid = document.querySelector('#bookmark-grid');
424	    const count = document.querySelector('#count');
425	    const detailsFields = document.querySelector('#details-fields');
426	    const titleInput = document.querySelector('#bookmark-title');
427	    const descriptionInput = document.querySelector('#bookmark-description');
428	    const mode = new URLSearchParams(window.location.search).get('edit');
429	    let loadedMetadata = null;
430	    let automaticTimer = null;
431	
432	    if (mode === 'guided') {
433	      document.querySelector('.dialog-head p').textContent = 'Paste the link first, then review what we find.';
434	      saveButton.textContent = 'Get details';
435	    } else if (mode === 'automatic') {
436	      document.querySelector('.dialog-head p').textContent = 'Paste the link and its details will appear here.';
437	      saveButton.disabled = true;
438	    }
439	
440	    document.querySelectorAll('.open-dialog').forEach(button => {
441	      button.addEventListener('click', () => {
442	        dialog.showModal();
443	        requestAnimationFrame(() => input.focus());
444	      });
445	    });
446	
447	    function closeDialog() {
448	      dialog.close();
449	      form.reset();
450	      detailsFields.classList.remove('visible');
451	      titleInput.disabled = true;
452	      descriptionInput.disabled = true;
453	      loadedMetadata = null;
454	      window.clearTimeout(automaticTimer);
455	      saveButton.disabled = mode === 'automatic';
456	      saveButton.textContent = mode === 'guided' ? 'Get details' : 'Save bookmark';
457	    }
458	
459	    document.querySelector('.close').addEventListener('click', closeDialog);
460	    document.querySelector('.cancel').addEventListener('click', closeDialog);
461	    dialog.addEventListener('click', event => {
462	      if (event.target === dialog) closeDialog();
463	    });
