465	    const exampleMetadata = {
466	      title: 'The Best Crispy Roast Potatoes Ever',
467	      description: 'These roast potatoes maximize the crisp-to-creamy contrast in every chunk, with a crunchy shell and a fluffy center.',
468	      site: 'Serious Eats',
469	      letter: 'S'
470	    };
471	
472	    function detailsFor(url) {
473	      const host = new URL(url).hostname.replace(/^www\./, '');
474	      const isExample = host.includes('seriouseats.com');
475	      return isExample ? {...exampleMetadata} : {
476	        title: 'A page worth coming back to',
477	        description: 'The page description has been collected automatically so you can recognize this bookmark later.',
478	        site: host,
479	        letter: host.charAt(0).toUpperCase()
480	      };
481	    }
482	
483	    function showEditableDetails(metadata) {
484	      loadedMetadata = metadata;
485	      titleInput.disabled = false;
486	      descriptionInput.disabled = false;
487	      titleInput.value = metadata.title;
488	      descriptionInput.value = metadata.description;
489	      detailsFields.classList.add('visible');
490	      saveButton.disabled = false;
491	      saveButton.textContent = 'Save bookmark';
492	      titleInput.focus();
493	      titleInput.select();
494	    }
495	
496	    function saveCard(url, metadata) {
497	      const finalTitle = mode ? titleInput.value.trim() : metadata.title;
498	      const finalDescription = mode ? descriptionInput.value.trim() : metadata.description;
499	      const card = document.createElement('article');
500	      card.className = 'card';
501	      card.innerHTML = `
502	        <div class="site"><span class="favicon">${metadata.letter}</span>${metadata.site}</div>
503	        <h2>${finalTitle}</h2>
504	        <p class="description">${finalDescription}</p>
505	        <div class="url">${url}</div>
506	      `;
507	
508	      grid.replaceChildren(card);
509	      emptyState.style.display = 'none';
510	      grid.style.display = 'grid';
511	      count.textContent = '1 saved';
512	      saveButton.disabled = mode === 'automatic';
513	      saveButton.textContent = mode === 'guided' ? 'Get details' : 'Save bookmark';
514	      dialog.close();
515	      form.reset();
516	      detailsFields.classList.remove('visible');
517	      titleInput.disabled = true;
518	      descriptionInput.disabled = true;
519	      loadedMetadata = null;
520	    }
521	
522	    if (mode === 'automatic') {
523	      input.addEventListener('input', () => {
524	        window.clearTimeout(automaticTimer);
525	        loadedMetadata = null;
526	        detailsFields.classList.remove('visible');
527	        titleInput.disabled = true;
528	        descriptionInput.disabled = true;
529	        saveButton.disabled = true;
530	        saveButton.textContent = 'Save bookmark';
531	        if (!input.validity.valid) return;
532	
533	        automaticTimer = window.setTimeout(() => {
534	          saveButton.innerHTML = '<span class="spinner" aria-hidden="true"></span> Getting details…';
535	          window.setTimeout(() => showEditableDetails(detailsFor(input.value.trim())), 650);
536	        }, 350);
537	      });
538	    }
539	
540	    form.addEventListener('submit', event => {
541	      event.preventDefault();
542	      if (!form.reportValidity()) return;
543	
544	      const url = input.value.trim();
545	
546	      if (mode && loadedMetadata) {
547	        saveCard(url, loadedMetadata);
548	        return;
549	      }
550	
551	      saveButton.disabled = true;
552	      saveButton.innerHTML = '<span class="spinner" aria-hidden="true"></span> Getting details…';
553	
554	      window.setTimeout(() => {
555	        const metadata = detailsFor(url);
556	        if (mode === 'guided') {
557	          showEditableDetails(metadata);
558	          return;
559	        }
560	        saveCard(url, metadata);
561	      }, 800);
562	    });
563	  </script>
564	</body>
565	</html>
