function addDraftLabel(value) {
  const label = value.trim();
  if (!label || draftLabels.some(item => item.toLowerCase() === label.toLowerCase())) return;
  draftLabels.push(label);
  setupLabelEditor(true);
}

function setupLabelEditor(focusNew = false) {
  const section = document.querySelector('#label-editor');
  const content = document.querySelector('#label-editor-content');
  section.classList.add('visible');
  if (!draftLabels.length) draftLabels = [...currentLabels];

  if (labelMode === 'type') {
    content.innerHTML = `<div class="selected-labels">${draftLabels.map(label => `<span class="label-pill">${label}</span>`).join('')}</div><input id="new-label" type="text" placeholder="Type a new label"><p class="label-hint">Press Enter to add another label.</p>`;
    const newLabel = document.querySelector('#new-label');
    newLabel.addEventListener('keydown', event => {
      if (event.key !== 'Enter') return;
      event.preventDefault();
      addDraftLabel(newLabel.value);
    });
    if (focusNew) newLabel.focus();
  } else {
    const choices = [...new Set(['Recipes', 'Work', 'Travel', 'Home', ...draftLabels])];
    content.innerHTML = `<div class="label-choices">${choices.map(label => `<label class="label-choice"><input type="checkbox" value="${label}" ${draftLabels.includes(label) ? 'checked' : ''}><span>${label}</span></label>`).join('')}</div><div class="label-create-row"><input id="new-label" type="text" placeholder="New label"><button class="secondary" id="create-label" type="button">Create & add</button></div>`;
    content.querySelectorAll('input[type="checkbox"]').forEach(box => box.addEventListener('change', () => {
      draftLabels = [...content.querySelectorAll('input[type="checkbox"]:checked')].map(item => item.value);
    }));
    document.querySelector('#create-label').addEventListener('click', () => addDraftLabel(document.querySelector('#new-label').value));
    if (focusNew) document.querySelector('#new-label').focus();
  }
}

function saveCard(url, metadata) {
  currentUrl = url;
  currentMetadata = metadata;
  currentTitle = mode ? titleInput.value.trim() : metadata.title;
  currentDescription = mode ? descriptionInput.value.trim() : metadata.description;
  renderCard(currentUrl, currentMetadata, currentTitle, currentDescription);
  saveButton.disabled = mode === 'automatic';
  saveButton.textContent = mode === 'guided' ? 'Get details' : 'Save bookmark';
  dialog.close();
  form.reset();
  detailsFields.classList.remove('visible');
  titleInput.disabled = true;
  descriptionInput.disabled = true;
  loadedMetadata = null;
}

editForm.addEventListener('submit', event => {
  event.preventDefault();
  if (!editForm.reportValidity()) return;
  currentTitle = editTitle.value.trim();
  currentDescription = editDescription.value.trim();
  if (labelMode) currentLabels = [...draftLabels];
  renderCard(currentUrl, currentMetadata, currentTitle, currentDescription);
  editDialog.close();
  draftLabels = [];
});

if (mode === 'automatic') {
  input.addEventListener('input', () => {
    window.clearTimeout(automaticTimer);
    loadedMetadata = null;
    detailsFields.classList.remove('visible');
    titleInput.disabled = true;
    descriptionInput.disabled = true;
    saveButton.disabled = true;
    saveButton.textContent = 'Save bookmark';
    if (!input.validity.valid) return;

    automaticTimer = window.setTimeout(() => {
      if (duplicateMode && input.value.trim() === currentUrl) {
        saveButton.innerHTML = '<span class="spinner" aria-hidden="true"></span> Checking collection…';
        window.setTimeout(() => {
          closeDialog();
          openExistingEditor('duplicate');
        }, 650);
        return;
      }
      saveButton.innerHTML = '<span class="spinner" aria-hidden="true"></span> Getting details…';
      window.setTimeout(() => showEditableDetails(detailsFor(input.value.trim())), 650);
    }, 350);
  });
}

form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.reportValidity()) return;

  const url = input.value.trim();

  if (mode && loadedMetadata) {
    saveCard(url, loadedMetadata);
    return;
  }

  saveButton.disabled = true;
  saveButton.innerHTML = '<span class="spinner" aria-hidden="true"></span> Getting details…';

  window.setTimeout(() => {
    const metadata = detailsFor(url);
    if (mode === 'guided') {
      showEditableDetails(metadata);
      return;
    }
    saveCard(url, metadata);
  }, 800);
});
